"""Reports-only presentation and controller over existing workspace records/exports."""

# ruff: noqa: E501, RUF001 - embedded assets follow the existing frontend architecture.

REPORTS_PANEL = r"""
<section id="reportsView" class="reports-workspace" data-workspace-view="reports" hidden>
 <div class="reports-hero">
  <div><span class="reports-eyebrow">RESEARCH &amp; OUTREACH</span><h2>Performance, in perspective.</h2><p>One research scope for your metrics, records and downloads.</p></div>
  <span class="reports-private"><span aria-hidden="true">●</span> Workspace records</span>
 </div>
 <div class="reports-scope reports-box">
  <div class="reports-scope-field"><label for="reportRun">Research scope</label><select id="reportRun"><option value="">All runs</option></select></div>
  <div class="reports-scope-meta"><strong id="reportScopeName">All research runs</strong><span id="reportUpdated">Ready to load</span></div>
  <button type="button" class="btn primary" id="refreshReportRuns">Refresh reports</button>
 </div>
 <div id="reportStatus" class="reports-notice" role="status" aria-live="polite"></div>
 <section class="reports-box" id="campaignAnalytics" aria-labelledby="analyticsTitle">
  <div class="reports-section-head"><div><span class="reports-eyebrow">01 / OVERVIEW</span><h3 id="analyticsTitle">Campaign analytics</h3></div><span class="reports-caption">Recorded activity, within the selected scope</span></div>
  <div id="reportMetrics" class="reports-metrics" aria-busy="true"></div>
  <div id="reportRates" class="reports-rates"></div>
  <details class="reports-definitions"><summary>How these numbers are calculated</summary><p id="reportDefinitions">Loading metric definitions…</p></details>
  <div id="reportAnalyticsStatus" class="reports-inline-status" role="status"></div>
 </section>
 <section class="reports-box" aria-labelledby="reportRecordsTitle">
  <div class="reports-section-head"><div><span class="reports-eyebrow">02 / RECORDS &amp; EXPORTS</span><h3 id="reportRecordsTitle">Explore your records</h3><p>Preview the matching rows before you download.</p></div><div class="reports-downloads"><button type="button" class="btn" id="reportCSV" data-report="leads" data-format="csv" disabled>Download leads CSV</button><button type="button" class="btn primary" id="reportExcel" data-report="leads" data-format="xlsx" disabled>Download leads Excel</button></div></div>
  <div class="reports-tabs" role="group" aria-label="Report dataset"><button type="button" data-report-dataset="leads" aria-pressed="true">Saved leads</button><button type="button" data-report-dataset="observations" aria-pressed="false">Collected profiles</button></div>
  <div class="reports-filters">
   <div id="reportQueryField"><label for="reportQuery">Find a lead</label><input id="reportQuery" type="search" maxlength="200" placeholder="Name, company, role or location"></div>
   <div id="reportLeadStatusField"><label for="reportLeadStatus">Lead review status</label><select id="reportLeadStatus"><option value="">All statuses</option></select></div>
   <div id="reportDecisionField" hidden><label for="reportDecision">Collection decision</label><select id="reportDecision"><option value="all">All collected profiles</option><option value="accepted">Accepted</option><option value="rejected">Rejected</option></select></div>
   <button type="button" class="btn" id="resetReportFilters">Reset filters</button>
  </div>
  <div class="reports-preview-meta"><strong id="reportMatchCount">Loading records…</strong><span id="reportFilterHint">Saved leads include qualification and review information.</span></div>
  <div class="reports-table-scroll"><table class="reports-table"><caption class="reports-sr">Filtered report preview</caption><thead id="reportPreviewHead"></thead><tbody id="reportPreviewRows"></tbody></table></div>
  <div id="reportPreviewEmpty" class="reports-empty" hidden><strong>No matching records</strong><p>Try another research run or clear the filters.</p></div>
  <div id="reportPreviewStatus" class="reports-inline-status" role="status"></div>
  <div class="reports-pagination"><span id="reportPage">—</span><div><button type="button" class="btn" id="reportPrevious" disabled>Previous</button><button type="button" class="btn" id="reportNext" disabled>Next</button></div></div>
  <p class="reports-export-note">Downloads include all matching rows across pages, up to 5,000. Larger selections require narrower filters.</p>
  <div id="reportExportStatus" class="reports-inline-status" role="status" aria-live="polite"></div>
 </section>
 <section class="reports-box" aria-labelledby="reportHistoryTitle">
  <div class="reports-section-head"><div><span class="reports-eyebrow">03 / RESEARCH HISTORY</span><h3 id="reportHistoryTitle">Recent research runs</h3><p>Choose a run to inspect its metrics and export its records.</p></div><span id="reportHistoryCount" class="reports-count">—</span></div>
  <div class="reports-table-scroll"><table class="reports-table"><caption class="reports-sr">Recent research runs within the selected scope</caption><thead><tr><th>Campaign / run</th><th>Created</th><th>Run status</th><th>Read</th><th>Accepted</th><th>Rejected</th><th>Report</th></tr></thead><tbody id="workspaceRunRows"></tbody></table></div>
  <div id="reportHistoryEmpty" class="reports-empty" hidden><strong>No research runs yet</strong><p>Start a search from Lead pipeline, then return here.</p></div>
  <div id="reportHistoryStatus" class="reports-inline-status" role="status"></div>
 </section>
</section>
"""

